-- =====================================================================
-- 50 MOCK PROPERTIES SEED DATA (PLOTS & FLATS, ₹10 Lakhs to ₹3 Cr)
-- Target DB: onenesgw_property_project / mannidam_property_db
-- =====================================================================

CREATE TABLE IF NOT EXISTS `user_browsing_analytics` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `user_phone` VARCHAR(20) NOT NULL,
    `property_id` VARCHAR(50) NOT NULL,
    `property_title` VARCHAR(255) NULL,
    `property_type` VARCHAR(100) NOT NULL,
    `price` VARCHAR(50) NOT NULL,
    `price_inr` BIGINT NOT NULL,
    `locality` VARCHAR(150) NULL,
    `city` VARCHAR(100) NULL,
    `action_type` VARCHAR(50) DEFAULT 'view',
    `viewed_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    KEY `idx_phone` (`user_phone`),
    KEY `idx_property` (`property_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

ON DUPLICATE KEY UPDATE title=VALUES(title), price=VALUES(price), price_per_sqft=VALUES(price_per_sqft), property_type=VALUES(property_type), status='published';


